const response = $input.first().json;

// ============================================
// 1. EXTRACT GEMINI RESPONSE TEXT
// ============================================

let data = response;

if (typeof response.text === 'string') {
  data = JSON.parse(response.text);

} else if (Array.isArray(response.output)) {

  const message = response.output.find(
    item => item.type === 'message'
  );

  const rawText = message?.content?.find(
    item => item.type === 'output_text'
  )?.text;

  if (!rawText) {
    throw new Error('Gemini returned no contents-page extraction text.');
  }

  const cleaned = rawText
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  try {
    data = JSON.parse(cleaned);
  } catch (error) {
    throw new Error(
      `Could not parse Gemini JSON: ${error.message}. Preview: ${cleaned.slice(0, 1500)}`
    );
  }

} else if (
  response.output &&
  typeof response.output === 'object' &&
  !Array.isArray(response.output)
) {
  data = response.output;
}

// ============================================
// 2. NORMALISE THE GEMINI RESPONSE
// ============================================

function getFirstDefined(object, keys) {
  if (!object || typeof object !== 'object') {
    return undefined;
  }

  for (const key of keys) {
    if (
      object[key] !== undefined &&
      object[key] !== null &&
      object[key] !== ''
    ) {
      return object[key];
    }
  }

  return undefined;
}

// Accept different possible page-number field names.
function getPdfPage(section) {
  const value = getFirstDefined(section, [
    'pdf_page_number',
    'physical_page_number',
    'calculated_pdf_page',
    'pdf_page',
    'page_number',
    'page',
    'start_page'
  ]);

  if (value === undefined) {
    return null;
  }

  const page = Number(value);

  return Number.isInteger(page) && page > 0
    ? page
    : null;
}

// Accept different possible heading field names.
function getSectionName(section) {
  const value = getFirstDefined(section, [
    'section_name',
    'heading',
    'title',
    'name'
  ]);

  return typeof value === 'string'
    ? value.trim()
    : '';
}

// Convert section arrays into a consistent structure.
function normaliseSections(input) {
  if (!Array.isArray(input)) {
    return [];
  }

  return input.map(section => {
    if (
      typeof section === 'string' ||
      typeof section === 'number'
    ) {
      return null;
    }

    if (!section || typeof section !== 'object') {
      return null;
    }

    return {
      section_name: getSectionName(section),

      printed_page_number: getFirstDefined(section, [
        'printed_page_number',
        'printed_page',
        'printed_page_no'
      ]) ?? null,

      pdf_page_number: getPdfPage(section)
    };
  }).filter(section =>
    section &&
    section.section_name &&
    section.pdf_page_number !== null
  );
}

// ============================================
// 3. GET ALL CONTENTS ENTRIES
// ============================================

// These entries are used to calculate section boundaries.

const allContentsInput = getFirstDefined(data, [
  'all_contents_entries',
  'allContentsEntries',
  'All_Contents_Entries',
  'contents_entries',
  'Contents_Entries'
]);

let allSections = normaliseSections(allContentsInput);

// Fallback: if Gemini returns a raw array, use it as the
// contents entries. Also supports older response formats.

if (allSections.length === 0 && Array.isArray(data)) {
  allSections = normaliseSections(data);
}

if (allSections.length === 0) {
  const fallbackInput = getFirstDefined(data, [
    'relevant_sections',
    'Relevant_Sections',
    'relevantSections'
  ]);

  allSections = normaliseSections(fallbackInput);
}

// ============================================
// 4. GET RELEVANT SECTIONS
// ============================================

// These entries determine which sections we actually extract.

const relevantInput = getFirstDefined(data, [
  'relevant_sections',
  'Relevant_Sections',
  'relevantSections'
]);

let relevantSections = normaliseSections(relevantInput);

// If Gemini did not return a separate relevant_sections array,
// use targeted keyword matching as a fallback.

if (relevantSections.length === 0) {

  const relevantKeywords = [
  'at a glance',                 
  'business model',             
  'business review',
  'operational review',
  'operational reviews',
  'operating review',
  'strategic and operating review',
  'business segments',
  'segment discussion',
  'segment review',
  'our divisions',
  'divisional review',
  'principal activities',
  'business unit',
    'sustainability',              
  'esg',                         
  'non-financial',               
  'nfsis',                       
  'responsible business', 
  'TCFD', 
  'climate',                    
  'people and planet',          
  'energy transition',         
  'greenhouse gas',
  ];

  relevantSections = allSections.filter(section => {
    const heading = section.section_name.toLowerCase();

    return relevantKeywords.some(keyword =>
      heading.includes(keyword)
    );
  });
}

// ============================================
// 5. VALIDATE CONTENTS ENTRIES
// ============================================

if (allSections.length === 0) {
  throw new Error(
    'No valid contents-page entries found. Check Gemini output for all_contents_entries and physical PDF page numbers.'
  );
}

if (relevantSections.length === 0) {
  throw new Error(
    'No relevant business sections were identified by Gemini or the fallback keyword filter.'
  );
}

// Sort all contents entries by physical PDF page number.
allSections.sort((a, b) =>
  a.pdf_page_number - b.pdf_page_number
);

// Remove duplicate headings at the same physical page.
allSections = allSections.filter((section, index, array) =>
  index === 0 ||
  section.pdf_page_number !== array[index - 1].pdf_page_number ||
  section.section_name !== array[index - 1].section_name
);

// Sort selected sections.
relevantSections.sort((a, b) =>
  a.pdf_page_number - b.pdf_page_number
);

// ============================================
// 6. DETERMINE TOTAL PDF PAGE COUNT
// ============================================

const totalPdfPagesValue = getFirstDefined(data, [
  'total_pdf_pages',
  'pdf_page_count',
  'total_pages'
]);

const totalPdfPages = Number(totalPdfPagesValue);

const validTotalPdfPages =
  Number.isInteger(totalPdfPages) && totalPdfPages > 0
    ? totalPdfPages
    : null;

// ============================================
// 7. CALCULATE SECTION PAGE RANGES
// ============================================

const selectedSections = [];
const allRelevantPages = [];
const boundaryWarnings = [];

for (const section of relevantSections) {

  const startPage = section.pdf_page_number;

  // Find the next heading in the COMPLETE contents list.
  // This is why all_contents_entries is important.

  const nextSection = allSections.find(entry =>
    entry.pdf_page_number > startPage
  );

  let endPage = null;

  if (nextSection) {

    // Stop immediately before the next contents heading.
    endPage = nextSection.pdf_page_number - 1;

  } else if (validTotalPdfPages) {

    // Use actual PDF page count if available.
    endPage = validTotalPdfPages;

  } else {

    // Do not guess the ending page.
    // Only select the known starting page.
    endPage = startPage;

    boundaryWarnings.push(
      `Could not determine the ending page for "${section.section_name}". Only page ${startPage} was selected because no following contents heading or PDF page count was available.`
    );
  }

  if (endPage < startPage) {
    boundaryWarnings.push(
      `Invalid page range for "${section.section_name}".`
    );
    continue;
  }

  const pages = [];

  for (let page = startPage; page <= endPage; page++) {
    pages.push(page);
    allRelevantPages.push(page);
  }

  selectedSections.push({
    section_name: section.section_name,
    printed_page_number: section.printed_page_number,
    start_page: startPage,
    end_page: endPage,
    page_count: pages.length,
    pages: pages
  });
}

// ============================================
// 8. REMOVE DUPLICATE PAGES
// ============================================

const relevantPages = [
  ...new Set(allRelevantPages)
].sort((a, b) => a - b);

if (relevantPages.length === 0) {
  throw new Error(
    'No physical PDF pages were selected for extraction.'
  );
}

// ============================================
// 9. IDENTIFY CONTENTS PAGE NUMBER
// ============================================

const contentsPageValue = getFirstDefined(data, [
  'table_of_contents_page',
  'contents_page_number',
  'table_of_contents_page_number',
  'contents_page'
]);

const contentsPageNumber = Number(contentsPageValue);

const validContentsPage =
  Number.isInteger(contentsPageNumber) &&
  contentsPageNumber > 0
    ? contentsPageNumber
    : null;

// ============================================
// 10. RETURN RESULTS
// ============================================

return [{
  json: {
    contents_page_number: validContentsPage,

    contents_complete:
      data.contents_complete ?? null,

    total_contents_headings: allSections.length,

    total_relevant_sections: selectedSections.length,

    starting_pages: selectedSections.map(section =>
      section.start_page
    ),

    selected_sections: selectedSections,

    relevant_pages: relevantPages,

    total_pages_selected: relevantPages.length,

    total_pdf_pages: validTotalPdfPages,

    boundary_warnings: boundaryWarnings
  }
}];

const isEval = $('Evaluation Trigger').isExecuted;
const input = isEval ? $('Evaluation Trigger').first().json : $('Start').first().json;

const parseIfNeeded = (val) => {
  if (typeof val === 'string' && val.trim().startsWith('{')) {
    try { return JSON.parse(val); } catch (e) { return val; }
  }
  return val;
};

return [{
  json: {
    filing_doc_url: input.filing_doc_url,
    Retrieve_stored_PDF_filing_doc_url: input.Retrieve_stored_PDF_filing_doc_url,
    _firstItem: parseIfNeeded(input._firstItem),
    Retrieve_File_Location__firstItem: parseIfNeeded(input.Retrieve_File_Location__firstItem),
    expected_segments: input.expected_segments || ''
  }
}];

const request = $('Normalize Inputs').first().json._firstItem || {};
const filing = $('Normalize Inputs').first().json.Retrieve_File_Location__firstItem || {};

const pageData = $('Parse Relevant Pages').first().json;
const relevantPages = pageData.relevant_pages;

const pageMapping = relevantPages
  .map((originalPage, index) =>
    `Merged PDF page ${index + 1} = Original PDF page ${originalPage}`
  )
  .join('\n');

return [{
  json: {
    company_id: request.company_id,
    company_name: request.company_name,
    company_crn: request.company_crn,
    filing_id: filing.filing_id,
    financial_year: filing.financial_year,
    input_type: 'pdf',
    extracted_text: null,
    file_url: $json.url,
    relevant_pages: relevantPages,
    pageMapping: pageMapping,
    extraction_method: 'pdfco_selected_pages'
  }
}];

const response = $input.first().json;
const pageData = $('Parse Relevant Pages').first().json;
const evalRow = $('Normalize Inputs').first().json;

let extracted = response;
if (Array.isArray(response.output)) {
  const message = response.output.find(item => item.type === 'message');
  const rawText = message?.content?.find(item => item.type === 'output_text')?.text || '';
  const cleaned = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
  try {
    extracted = JSON.parse(cleaned);
  } catch (e) {
    return [{
      json: {
        valid_json: 0,
        segment_count: 0,
        page_citation_accuracy: 0,
        has_boundary_warnings: (pageData.boundary_warnings?.length || 0) > 0 ? 1 : 0,
        parse_error: e.message,
        extracted: null,
        expected_segments: evalRow.expected_segments || ''
      }
    }];
  }
}

const segments = Array.isArray(extracted.business_segments) ? extracted.business_segments : [];
const allowedPages = new Set(pageData.relevant_pages || []);

function expandPages(pageStr) {
  if (!pageStr || typeof pageStr !== 'string') return [];
  const pages = [];
  for (const part of pageStr.split(',')) {
    const trimmed = part.trim();
    if (trimmed.includes('-')) {
      const [start, end] = trimmed.split('-').map(Number);
      if (Number.isInteger(start) && Number.isInteger(end) && end >= start) {
        for (let p = start; p <= end; p++) pages.push(p);
      }
    } else {
      const num = Number(trimmed);
      if (Number.isInteger(num)) pages.push(num);
    }
  }
  return pages;
}

let validCitations = 0;
for (const seg of segments) {
  const cited = expandPages(seg.source_page);
  const allInBounds = cited.length > 0 && cited.every(p => allowedPages.has(p));
  if (allInBounds) validCitations++;
}

const pageCitationAccuracy = segments.length > 0 ? Number((validCitations / segments.length).toFixed(2)) : 0;

return [{
  json: {
    valid_json: 1,
    segment_count: segments.length,
    page_citation_accuracy: pageCitationAccuracy,
    total_pages_selected: pageData.total_pages_selected || 0,
    has_boundary_warnings: (pageData.boundary_warnings?.length || 0) > 0 ? 1 : 0,
    extracted,
    expected_segments: evalRow.expected_segments || ''
  }
}];

