const response = $input.first().json;
const priorData = $('Evaluate Extraction Structure & Citations').first().json;
let scores = { segment_recall: 0, rule_compliance: 0, critique: "Failed to parse judge output" };

try {
  const message = response.output.find(item => item.type === 'message');
  const rawText = message?.content?.find(item => item.type === 'output_text')?.text || '';
  const cleaned = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
  scores = JSON.parse(cleaned);
} catch (e) {}

return [{
  json: {
    ...priorData,
    segment_recall: scores.segment_recall || 0,
    rule_compliance: scores.rule_compliance || 0,
    critique: scores.critique || ""
  }
}];
